import { createFileRoute } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import { useEffect, useMemo, useState, type FormEvent } from "react";
import type { Session } from "@supabase/supabase-js";
import { supabase } from "@/integrations/supabase/client";
import { lovable } from "@/integrations/lovable/index";
import { Button } from "@/components/ui/button";
import { Activity, CalendarDays, ChartNoAxesCombined, Check, ChevronLeft, ChevronRight, ClipboardList, Download, LayoutDashboard, LogOut, Menu, Plus, Search, Settings2, Trash2, Users, X, Building2, Paperclip, Pencil, Target } from "lucide-react";
import ari from "@/assets/logo_ari-2.png.asset.json";
import uel from "@/assets/UEL-horizontal-abreviada-cor.png.asset.json";
import araucaria from "@/assets/logo_araucaria.png.asset.json";
import sebrae from "@/assets/logo_sebrae.png.asset.json";
import parana from "@/assets/logo_pr.png.asset.json";
import type { Database, Json } from "@/integrations/supabase/types";
import { registerAccount } from "@/lib/account.functions";

type ActivityRow = Database["public"]["Tables"]["activities"]["Row"];
type Organization = Database["public"]["Tables"]["organizations"]["Row"];
type Actor = Database["public"]["Tables"]["actors"]["Row"];
type Profile = Database["public"]["Tables"]["profiles"]["Row"];
type CoordinationParticipant = Database["public"]["Functions"]["coordination_participants"]["Returns"][number];
type Section = "overview" | "activities" | "calendar" | "organizations" | "actors" | "agents" | "reports";
const activityKinds = ["Atividade do plano de estratégias", "Atividade geral", "Evento como ouvinte", "Evento como organizador", "Reunião de governança", "Reunião com a coordenação", "Outras reuniões"];
const axes = ["Governança do Ecossistema", "Programas e Ações de Inovação", "Comunidade Empreendedora", "Ambiente de Inovação", "Relação Academia/Empresa", "Políticas Públicas", "Comunicação", "Captação de Recursos", "Sensibilização de Atores", "Setorial"];
const statuses = ["Não iniciada", "Iniciada", "Concluída"];
const stages = ["Prospecção", "Diagnóstico", "Encaminhamento", "Acompanhamento"];
const nav: { id: Section; label: string; icon: typeof Activity }[] = [
  { id: "overview", label: "Visão geral", icon: LayoutDashboard }, { id: "activities", label: "Atividades", icon: ClipboardList },
  { id: "calendar", label: "Agenda", icon: CalendarDays }, { id: "organizations", label: "Organizações", icon: Building2 },
  { id: "actors", label: "Atores da governança", icon: Users }, { id: "agents", label: "Agentes", icon: Activity },
  { id: "reports", label: "Relatórios", icon: ChartNoAxesCombined },
];
const formatDate = (value?: string | null) => value ? new Date(`${value}T12:00:00`).toLocaleDateString("pt-BR") : "—";
const monthLabel = (d: Date) => d.toLocaleDateString("pt-BR", { month: "long", year: "numeric" });
const initials = (value: string) => value.split(" ").filter(Boolean).slice(0, 2).map(x => x[0]).join("").toUpperCase() || "AR";
const field = (label: string, name: string, value: string, set: (name: string, value: string) => void, opts?: { type?: string; options?: (string | { value: string; label: string })[]; textarea?: boolean; required?: boolean }) => <label className="block min-w-0"><span className="app-label">{label}</span>{opts?.textarea ? <textarea className="app-field min-h-24 resize-y" value={value} onChange={e => set(name, e.target.value)} required={opts.required} /> : opts?.options ? <select className="app-field" value={value} onChange={e => set(name, e.target.value)}><option value="">Selecione</option>{opts.options.map(x => typeof x === "string" ? <option key={x} value={x}>{x}</option> : <option key={x.value} value={x.value}>{x.label}</option>)}</select> : <input className="app-field" type={opts?.type || "text"} value={value} onChange={e => set(name, e.target.value)} required={opts?.required} />}</label>;
const partners = [{ src: uel.url, alt: "Universidade Estadual de Londrina" }, { src: araucaria.url, alt: "Fundação Araucária" }, { src: sebrae.url, alt: "Sebrae" }, { src: parana.url, alt: "Governo do Estado do Paraná" }];

export const Route = createFileRoute("/")({
  head: () => ({ meta: [
    { title: "ARI | Gestão de Atividades" },
    { name: "description", content: "Planejamento, registro e acompanhamento das ações dos Agentes Regionais de Inovação vinculados à UEL." },
    { property: "og:title", content: "ARI | Gestão de Atividades" },
    { property: "og:description", content: "Sistema de atividades e indicadores dos Agentes Regionais de Inovação da UEL." },
    { property: "og:type", content: "website" }, { name: "twitter:card", content: "summary_large_image" },
  ] }), component: Index,
});

function Index() {
  const [session, setSession] = useState<Session | null>(null);
  const [ready, setReady] = useState(false);
  useEffect(() => { supabase.auth.getSession().then(({ data }) => { setSession(data.session); setReady(true); }); const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, next) => { setSession(next); setReady(true); }); return () => subscription.unsubscribe(); }, []);
  if (!ready) return <div className="min-h-screen flex items-center justify-center text-muted-foreground">Carregando...</div>;
  return session ? <Workspace session={session} /> : <Login />;
}

function Footer() { return <footer className="border-t bg-card px-5 py-7 md:px-10"><div className="mx-auto max-w-7xl flex flex-col items-center justify-between gap-6 lg:flex-row"><p className="text-xs text-muted-foreground text-center lg:text-left">ARI · Agentes Regionais de Inovação<br />Universidade Estadual de Londrina</p><div className="flex flex-wrap items-center justify-center gap-x-8 gap-y-5">{partners.map(p => <img key={p.alt} src={p.src} alt={p.alt} className="h-9 max-w-32 object-contain md:h-11" />)}</div></div></footer>; }

function Login() {
  const [mode, setMode] = useState<"login" | "register" | "reset">("login");
  const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [name, setName] = useState("");
  const [accountType, setAccountType] = useState<"agent" | "coordinator">("agent");
  const [message, setMessage] = useState(""); const [busy, setBusy] = useState(false);
  const register = useServerFn(registerAccount);
  async function submit(e: FormEvent) { e.preventDefault(); setBusy(true); setMessage("");
    try {
      if (mode === "reset") { const { error } = await supabase.auth.resetPasswordForEmail(email, { redirectTo: window.location.origin }); setMessage(error?.message || "Enviamos um link de recuperação para seu e-mail."); }
      else if (mode === "register") { const result = await register({ data: { name, email, password, role: accountType } }); setMessage(result.requiresEmailConfirmation ? "Cadastro realizado. Confirme seu e-mail para acessar o sistema." : "Cadastro realizado. Você já pode entrar."); }
      else { const { error } = await supabase.auth.signInWithPassword({ email, password }); if (error) setMessage("Não foi possível entrar. Confira e-mail e senha."); }
    } catch (error) { setMessage(error instanceof Error ? error.message : "Não foi possível concluir o cadastro."); }
    finally { setBusy(false); }
  }
  async function google() { setBusy(true); const result = await lovable.auth.signInWithOAuth("google", { redirect_uri: window.location.origin }); if (result.error) { setMessage("Não foi possível entrar com Google. Tente novamente."); setBusy(false); } }
  return <div className="min-h-screen flex flex-col"><div className="flex-1 grid lg:grid-cols-[1fr_1fr]"><div className="bg-sidebar text-primary-foreground flex flex-col justify-between p-8 lg:p-14 min-h-72"><img src={ari.url} alt="ARI — Agente Regional de Inovação" className="w-48 md:w-60 object-contain" /><div className="max-w-lg py-12"><p className="text-sm font-bold uppercase text-accent tracking-widest">Universidade Estadual de Londrina</p><h1 className="mt-5 text-4xl md:text-5xl font-bold leading-tight">Inovação começa com conexões.</h1><p className="mt-5 text-primary-foreground/75 text-lg leading-relaxed">Um espaço para organizar as ações, acompanhar resultados e fortalecer o ecossistema regional.</p></div><p className="text-sm text-primary-foreground/60">Plataforma de gestão · ARI</p></div><div className="flex items-center justify-center p-6 md:p-12"><div className="w-full max-w-sm"><p className="text-sm text-primary font-bold">BEM-VINDO AO ARI</p><h2 className="text-3xl font-bold mt-2">{mode === "login" ? "Acesse sua conta" : mode === "register" ? "Criar uma conta" : "Recuperar senha"}</h2><p className="text-muted-foreground text-sm mt-2 mb-8">{mode === "login" ? "Entre para acompanhar suas atividades e resultados." : mode === "register" ? "Preencha seus dados para começar." : "Enviaremos um link para o seu e-mail."}</p><form className="space-y-4" onSubmit={submit}>{mode === "register" && field("Nome completo", "name", name, (_, v) => setName(v), { required: true })}{field("E-mail", "email", email, (_, v) => setEmail(v), { type: "email", required: true })}{mode !== "reset" && field("Senha", "password", password, (_, v) => setPassword(v), { type: "password", required: true })}{message && <p role="status" className="text-sm text-primary bg-secondary p-3 rounded-md">{message}</p>}<Button type="submit" size="lg" className="w-full" disabled={busy}>{busy ? "Aguarde..." : mode === "login" ? "Entrar" : mode === "register" ? "Criar conta" : "Enviar link"}</Button></form>{mode === "login" && <><div className="relative my-6 text-center text-xs text-muted-foreground before:absolute before:top-1/2 before:left-0 before:w-2/5 before:border-t after:absolute after:top-1/2 after:right-0 after:w-2/5 after:border-t">ou</div><Button variant="outline" className="w-full" onClick={google} disabled={busy}>Continuar com Google</Button></>}<div className="mt-7 flex flex-wrap justify-between gap-3 text-sm"><Button variant="link" className="p-0" onClick={() => { setMessage(""); setMode(mode === "register" ? "login" : "register"); }}>{mode === "register" ? "Já tenho uma conta" : "Criar conta"}</Button><Button variant="link" className="p-0" onClick={() => { setMessage(""); setMode(mode === "reset" ? "login" : "reset"); }}>{mode === "reset" ? "Voltar para entrar" : "Esqueci minha senha"}</Button></div></div></div></div><Footer /></div>;
}

function Workspace({ session }: { session: Session }) {
  const [section, setSection] = useState<Section>("overview"); const [mobileNav, setMobileNav] = useState(false);
  const [activities, setActivities] = useState<ActivityRow[]>([]); const [organizations, setOrganizations] = useState<Organization[]>([]); const [actors, setActors] = useState<Actor[]>([]); const [profiles, setProfiles] = useState<Profile[]>([]);
  const [role, setRole] = useState("agent"); const [coordinationParticipants, setCoordinationParticipants] = useState<CoordinationParticipant[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [toast, setToast] = useState("");
  const [modal, setModal] = useState<"activity" | "organization" | "actor" | "profile" | null>(null); const [editing, setEditing] = useState<ActivityRow | Organization | Actor | null>(null);
  const [query, setQuery] = useState(""); const [statusFilter, setStatusFilter] = useState(""); const [kindFilter, setKindFilter] = useState(""); const [month, setMonth] = useState(() => new Date());
  const isManager = role === "admin" || role === "coordinator"; const readOnly = role === "viewer" || role === "coordinator";
   async function load() { setLoading(true); const [a, o, t, p, r, participants] = await Promise.all([supabase.from("activities").select("*").order("created_at", { ascending: false }), supabase.from("organizations").select("*").order("created_at", { ascending: false }), supabase.from("actors").select("*").order("created_at", { ascending: false }), supabase.from("profiles").select("*"), supabase.from("user_roles").select("role").eq("user_id", session.user.id).limit(1), supabase.rpc("coordination_participants")]); setActivities(a.data || []); setOrganizations(o.data || []); setActors(t.data || []); setProfiles(p.data || []); setCoordinationParticipants(participants.data || []); if (!p.error && !p.data?.some(profile => profile.id === session.user.id)) { const { data: created } = await supabase.from("profiles").upsert({ id: session.user.id, full_name: String(session.user.user_metadata?.["full_name"] || session.user.email?.split("@")[0] || "Agente") }).select().single(); if (created) { setProfiles(current => [...current, created]); const refreshed = await supabase.rpc("coordination_participants"); if (!refreshed.error) setCoordinationParticipants(refreshed.data || []); } } setRole(r.data?.[0]?.role || "agent"); setError([a.error, o.error, t.error, p.error, participants.error].filter(Boolean).map(x => x?.message).join(" · ")); setLoading(false); }
  useEffect(() => { void load(); }, [session.user.id]);
  const myProfile = profiles.find(p => p.id === session.user.id);
  const displayName = myProfile?.full_name || session.user.user_metadata?.["full_name"] || session.user.email?.split("@")[0] || "Agente";
  const filtered = useMemo(() => activities.filter(a => (!query || `${a.title} ${a.description} ${a.kind}`.toLowerCase().includes(query.toLowerCase())) && (!statusFilter || a.status === statusFilter) && (!kindFilter || a.kind === kindFilter)), [activities, query, statusFilter, kindFilter]);
  function open(which: typeof modal, row: typeof editing = null) { if (readOnly) return; setEditing(row); setModal(which); }
  async function remove(which: "activities" | "organizations" | "actors", id: string) { if (!window.confirm("Excluir este registro? Esta ação não pode ser desfeita.")) return; const { error } = await supabase.from(which).delete().eq("id", id); if (error) setToast(`Não foi possível excluir: ${error.message}`); else { setToast("Registro excluído."); void load(); } }
  function exportCSV() { const headers = ["Título", "Tipo", "Status", "Início", "Conclusão", "Organização", "Responsável", "Resultados alcançados"]; const rows = filtered.map(a => [a.title, a.kind, a.status, formatDate(a.start_date), formatDate(a.end_date), organizations.find(o => o.id === a.organization_id)?.name || "", profiles.find(p => p.id === a.owner_id)?.full_name || "", a.achieved_results || ""]); const csv = [headers, ...rows].map(row => row.map(cell => `"${String(cell).replaceAll('"', '""')}"`).join(";")).join("\r\n"); const url = URL.createObjectURL(new Blob(["\uFEFF", csv], { type: "text/csv;charset=utf-8" })); const link = document.createElement("a"); link.href = url; link.download = "relatorio-ari.csv"; link.click(); URL.revokeObjectURL(url); }
  const heading = nav.find(x => x.id === section)?.label || "Visão geral";
  return <div className="min-h-screen flex flex-col lg:flex-row"><aside className={`no-print bg-sidebar text-primary-foreground lg:w-60 lg:shrink-0 lg:min-h-screen ${mobileNav ? "block" : "hidden lg:block"}`}><div className="lg:sticky lg:top-0 flex flex-col lg:h-screen"><div className="px-6 py-6 border-b border-primary-foreground/10"><img src={ari.url} alt="ARI" className="w-32 h-16 object-contain" /><p className="text-[11px] text-primary-foreground/60 mt-3 uppercase font-bold">Gestão de atividades</p></div><nav className="flex-1 px-3 py-6 space-y-1">{nav.map(item => { const Icon = item.icon; return <Button key={item.id} variant="ghost" onClick={() => { setSection(item.id); setMobileNav(false); setQuery(""); }} className={`w-full justify-start h-10 px-3 text-sm ${section === item.id ? "bg-primary-foreground/15 text-primary-foreground hover:bg-primary-foreground/20 hover:text-primary-foreground" : "text-primary-foreground/70 hover:bg-primary-foreground/10 hover:text-primary-foreground"}`}><Icon className="mr-2" />{item.label}</Button>; })}</nav><div className="p-3 border-t border-primary-foreground/10"><Button variant="ghost" className="w-full justify-start text-primary-foreground/70 hover:text-primary-foreground hover:bg-primary-foreground/10" onClick={() => open("profile")}><Settings2 /> Meu perfil</Button><Button variant="ghost" className="w-full justify-start text-primary-foreground/70 hover:text-primary-foreground hover:bg-primary-foreground/10" onClick={() => supabase.auth.signOut()}><LogOut /> Sair</Button></div></div></aside><div className="min-w-0 flex-1 flex flex-col"><header className="no-print bg-card border-b px-5 md:px-9 h-18 flex items-center justify-between gap-3"><div className="flex items-center gap-3"><Button variant="ghost" size="icon" className="lg:hidden" aria-label="Abrir menu" onClick={() => setMobileNav(!mobileNav)}><Menu /></Button><div><p className="text-xs text-muted-foreground">ARI / Plataforma de gestão</p><h1 className="font-bold text-lg">{heading}</h1></div></div><div className="flex items-center gap-3"><span className="hidden sm:block text-right"><span className="block text-sm font-bold">{displayName}</span><span className="block text-xs text-muted-foreground">{isManager ? "Coordenação" : readOnly ? "Visualizador" : "Agente regional"}</span></span><div className="w-9 h-9 rounded-full bg-accent text-accent-foreground grid place-items-center text-xs font-bold">{initials(displayName)}</div></div></header><main className="flex-1 p-5 md:p-9 max-w-[1600px] w-full mx-auto">{error && <p className="mb-5 p-3 rounded bg-secondary text-primary text-sm">Não foi possível carregar alguns dados: {error}</p>}{toast && <div role="status" className="mb-5 p-3 flex justify-between gap-3 rounded bg-accent text-accent-foreground text-sm">{toast}<Button variant="ghost" size="icon" className="h-5 w-5" aria-label="Fechar mensagem" onClick={() => setToast("")}><X /></Button></div>}{loading ? <p className="text-muted-foreground">Carregando registros...</p> : <>
    {section === "overview" && <><div className="mb-8 flex flex-wrap items-end justify-between gap-4"><div><p className="text-sm font-semibold text-primary">PAINEL DE ACOMPANHAMENTO</p><h2 className="text-2xl md:text-3xl font-bold mt-1">Olá, {displayName.split(" ")[0]}.</h2><p className="text-muted-foreground mt-2 text-sm">Acompanhe o trabalho realizado no ecossistema de inovação.</p></div>{!readOnly && <Button onClick={() => open("activity")}><Plus /> Nova atividade</Button>}</div><div className="grid sm:grid-cols-2 xl:grid-cols-4 gap-4"><Metric icon={ClipboardList} label="Atividades registradas" value={activities.length} note="Total de ações" /><Metric icon={Check} label="Concluídas" value={activities.filter(a => a.status === "Concluída").length} note="Ações finalizadas" /><Metric icon={Building2} label="Organizações" value={organizations.length} note="No ecossistema" /><Metric icon={Users} label="Atores cadastrados" value={actors.length} note="Na governança" /></div><div className="grid xl:grid-cols-[1.6fr_1fr] gap-7 mt-9"><div><SectionTitle title="Atividades recentes" action="Ver todas" onAction={() => setSection("activities")} /><div className="app-panel overflow-x-auto"><ActivityTable rows={activities.slice(0, 6)} organizations={organizations} onEdit={a => open("activity", a)} onDelete={a => remove("activities", a.id)} readOnly={readOnly} /></div></div><div><SectionTitle title="Próximos compromissos" action="Ver agenda" onAction={() => setSection("calendar")} /><div className="app-panel p-5 space-y-4">{activities.filter(a => a.start_date && a.start_date >= new Date().toISOString().slice(0, 10) && a.status !== "Concluída").sort((a,b) => (a.start_date || "").localeCompare(b.start_date || "")).slice(0, 4).map(a => <div key={a.id} className="flex gap-4 border-b last:border-0 pb-4 last:pb-0"><div className="text-center bg-secondary text-primary rounded p-2 min-w-12"><span className="block font-bold text-lg leading-none">{a.start_date?.slice(8,10)}</span><span className="text-[10px] uppercase">{new Date(`${a.start_date}T12:00:00`).toLocaleDateString("pt-BR", { month: "short" })}</span></div><div><p className="text-sm font-bold">{a.title}</p><p className="text-xs text-muted-foreground mt-1">{a.kind}</p></div></div>)}{!activities.some(a => a.start_date && a.start_date >= new Date().toISOString().slice(0, 10) && a.status !== "Concluída") && <Empty text="Nenhum compromisso futuro registrado." />}</div></div></div></>}
    {section === "activities" && <><Toolbar title="Atividades" subtitle="Registre e acompanhe as ações dos agentes regionais." action="Nova atividade" onAction={() => open("activity")} readOnly={readOnly} /><div className="flex flex-wrap gap-3 mb-5"><SearchBox value={query} onChange={setQuery} placeholder="Buscar atividades..." /><select className="app-field w-full sm:w-48" value={kindFilter} onChange={e => setKindFilter(e.target.value)}><option value="">Todos os tipos</option>{activityKinds.map(x => <option key={x}>{x}</option>)}</select><select className="app-field w-full sm:w-44" value={statusFilter} onChange={e => setStatusFilter(e.target.value)}><option value="">Todos os status</option>{statuses.map(x => <option key={x}>{x}</option>)}</select></div><div className="app-panel overflow-x-auto"><ActivityTable rows={filtered} organizations={organizations} onEdit={a => open("activity", a)} onDelete={a => remove("activities", a.id)} readOnly={readOnly} /></div></>}
    {section === "calendar" && <><Toolbar title="Agenda" subtitle="Visualize suas atividades e compromissos por data." action="Agendar atividade" onAction={() => open("activity")} readOnly={readOnly} /><div className="app-panel"><div className="p-5 border-b flex items-center justify-between"><h3 className="font-bold capitalize text-lg">{monthLabel(month)}</h3><div className="flex gap-1"><Button variant="outline" size="icon" aria-label="Mês anterior" onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth()-1, 1))}><ChevronLeft /></Button><Button variant="outline" size="icon" aria-label="Próximo mês" onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth()+1, 1))}><ChevronRight /></Button></div></div><CalendarGrid date={month} rows={activities} onSelect={a => { if (!readOnly) open("activity", a); }} /></div></>}
    {section === "organizations" && <><Toolbar title="Organizações atendidas" subtitle="Empresas, startups e instituições do ecossistema." action="Nova organização" onAction={() => open("organization")} readOnly={readOnly} /><div className="mb-5"><SearchBox value={query} onChange={setQuery} placeholder="Buscar organização..." /></div><div className="app-panel overflow-x-auto"><table className="w-full text-sm text-left"><thead className="bg-muted text-muted-foreground text-xs uppercase"><tr><th className="p-4">Organização</th><th className="p-4">Tipo / setor</th><th className="p-4">Região</th><th className="p-4">Etapa</th><th className="p-4">Contato</th><th className="p-4 w-24">Ações</th></tr></thead><tbody>{organizations.filter(o => `${o.name} ${o.sector} ${o.region}`.toLowerCase().includes(query.toLowerCase())).map(o => <tr key={o.id} className="border-t hover:bg-muted/40"><td className="p-4 font-bold">{o.name}<span className="block text-xs font-normal text-muted-foreground">{o.document}</span></td><td className="p-4">{o.kind}<span className="block text-xs text-muted-foreground">{o.sector}</span></td><td className="p-4">{o.region || "—"}</td><td className="p-4"><span className="rounded bg-secondary text-secondary-foreground px-2 py-1 text-xs">{o.stage}</span></td><td className="p-4">{o.contact || o.email || "—"}</td><td className="p-4"><RowActions edit={() => open("organization", o)} remove={() => remove("organizations", o.id)} readOnly={readOnly} /></td></tr>)}</tbody></table>{organizations.length === 0 && <Empty text="Nenhuma organização cadastrada." />}</div></>}
    {section === "actors" && <><Toolbar title="Atores da governança" subtitle="Pessoas e instituições que fazem parte da rede." action="Novo ator" onAction={() => open("actor")} readOnly={readOnly} /><div className="mb-5"><SearchBox value={query} onChange={setQuery} placeholder="Buscar ator ou instituição..." /></div><div className="app-panel overflow-x-auto"><table className="w-full text-sm text-left"><thead className="bg-muted text-muted-foreground text-xs uppercase"><tr><th className="p-4">Ator</th><th className="p-4">Instituição</th><th className="p-4">Tipo</th><th className="p-4">Contato</th><th className="p-4 w-24">Ações</th></tr></thead><tbody>{actors.filter(a => `${a.actor_name} ${a.institution_name}`.toLowerCase().includes(query.toLowerCase())).map(a => <tr key={a.id} className="border-t hover:bg-muted/40"><td className="p-4 font-bold">{a.actor_name}<span className="block text-xs font-normal text-muted-foreground">{a.position}</span></td><td className="p-4">{a.institution_name}</td><td className="p-4">{a.institution_type || "—"}</td><td className="p-4">{a.email || a.phone || "—"}</td><td className="p-4"><RowActions edit={() => open("actor", a)} remove={() => remove("actors", a.id)} readOnly={readOnly} /></td></tr>)}</tbody></table>{actors.length === 0 && <Empty text="Nenhum ator cadastrado." />}</div></>}
    {section === "agents" && <><Toolbar title="Agentes regionais" subtitle="Profissionais vinculados ao programa ARI." /><div className="grid md:grid-cols-2 xl:grid-cols-3 gap-4">{profiles.map(p => <div className="app-panel p-5 flex items-start gap-4" key={p.id}><div className="w-11 h-11 shrink-0 rounded-full bg-secondary text-primary grid place-items-center font-bold">{initials(p.full_name)}</div><div className="min-w-0"><h3 className="font-bold">{p.full_name || "Agente regional"}</h3><p className="text-sm text-muted-foreground mt-1">{p.region || "Região não informada"}</p><p className="text-xs text-muted-foreground mt-2">{p.governance || "Governança não informada"}</p>{p.phone && <p className="text-xs mt-2">{p.phone}</p>}</div></div>)}{profiles.length === 0 && <div className="app-panel p-5"><Empty text="Nenhum perfil de agente preenchido ainda. Atualize seu perfil para aparecer aqui." /></div>}</div></>}
    {section === "reports" && <><div className="flex flex-wrap justify-between gap-4 mb-7"><div><h2 className="text-2xl font-bold">Relatórios e indicadores</h2><p className="text-sm text-muted-foreground mt-1">Resultados consolidados das atividades cadastradas.</p></div><div className="flex gap-2 no-print"><Button variant="outline" onClick={() => window.print()}><Download /> Imprimir</Button><Button onClick={exportCSV}><Download /> Exportar CSV</Button></div></div><div className="grid sm:grid-cols-2 xl:grid-cols-4 gap-4 mb-8"><Metric icon={ClipboardList} label="Atividades" value={activities.length} note="Registradas" /><Metric icon={Check} label="Concluídas" value={activities.filter(a => a.status === "Concluída").length} note="Finalizadas" /><Metric icon={Building2} label="Organizações" value={organizations.length} note="Cadastradas" /><Metric icon={Target} label="Taxa de conclusão" value={`${activities.length ? Math.round(activities.filter(a => a.status === "Concluída").length / activities.length * 100) : 0}%`} note="Das ações registradas" /></div><div className="grid lg:grid-cols-2 gap-6"><div className="app-panel p-6"><h3 className="font-bold mb-6">Atividades por tipo</h3><div className="space-y-4">{activityKinds.map(kind => <Bar key={kind} label={kind} count={activities.filter(a => a.kind === kind).length} total={activities.length} />)}</div></div><div className="app-panel p-6"><h3 className="font-bold mb-6">Situação das atividades</h3><div className="space-y-4">{statuses.map(status => <Bar key={status} label={status} count={activities.filter(a => a.status === status).length} total={activities.length} />)}</div><h3 className="font-bold mt-10 mb-5">Etapas de atendimento</h3><div className="space-y-4">{stages.map(stage => <Bar key={stage} label={stage} count={organizations.filter(o => o.stage === stage).length} total={organizations.length} />)}</div></div></div><div className="app-panel mt-6 overflow-x-auto"><ActivityTable rows={filtered} organizations={organizations} onEdit={a => open("activity", a)} onDelete={a => remove("activities", a.id)} readOnly /></div></>}
   </>}</main><Footer /></div>{modal && <Editor kind={modal} row={editing} userId={session.user.id} userName={displayName} organizations={organizations} actors={actors} coordinationParticipants={coordinationParticipants} onClose={() => setModal(null)} onSaved={() => { setModal(null); setToast("Registro salvo com sucesso."); void load(); }} onError={setToast} />}</div>;
}
function Metric({ icon: Icon, label, value, note }: { icon: typeof Activity; label: string; value: string | number; note: string }) { return <div className="app-panel p-5"><div className="flex items-center justify-between"><span className="text-sm text-muted-foreground">{label}</span><div className="p-2 bg-secondary text-primary rounded"><Icon size={19} /></div></div><p className="text-3xl font-bold mt-4">{value}</p><p className="text-xs text-muted-foreground mt-1">{note}</p></div>; }
function SectionTitle({ title, action, onAction }: { title: string; action: string; onAction: () => void }) { return <div className="flex items-center justify-between mb-4"><h3 className="text-lg font-bold">{title}</h3><Button variant="link" className="p-0 text-xs" onClick={onAction}>{action} <ChevronRight /></Button></div>; }
function Toolbar({ title, subtitle, action, onAction, readOnly }: { title: string; subtitle: string; action?: string; onAction?: () => void; readOnly?: boolean }) { return <div className="flex flex-wrap items-end justify-between gap-4 mb-7"><div><h2 className="text-2xl font-bold">{title}</h2><p className="text-sm text-muted-foreground mt-1">{subtitle}</p></div>{action && !readOnly && <Button onClick={onAction}><Plus />{action}</Button>}</div>; }
function SearchBox({ value, onChange, placeholder }: { value: string; onChange: (v: string) => void; placeholder: string }) { return <div className="relative w-full sm:w-72"><Search size={16} className="absolute left-3 top-3 text-muted-foreground" /><input className="app-field pl-9" value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} /></div>; }
function Empty({ text }: { text: string }) { return <div className="py-12 text-center text-sm text-muted-foreground">{text}</div>; }
function RowActions({ edit, remove, readOnly }: { edit: () => void; remove: () => void; readOnly?: boolean }) { return readOnly ? null : <div className="flex gap-1"><Button variant="ghost" size="icon" title="Editar" aria-label="Editar" onClick={edit}><Pencil /></Button><Button variant="ghost" size="icon" title="Excluir" aria-label="Excluir" onClick={remove}><Trash2 /></Button></div>; }
function ActivityTable({ rows, organizations, onEdit, onDelete, readOnly }: { rows: ActivityRow[]; organizations: Organization[]; onEdit: (a: ActivityRow) => void; onDelete: (a: ActivityRow) => void; readOnly?: boolean }) { return <><table className="w-full text-sm text-left"><thead className="bg-muted text-muted-foreground text-xs uppercase"><tr><th className="p-4">Atividade</th><th className="p-4">Tipo</th><th className="p-4">Organização</th><th className="p-4">Data</th><th className="p-4">Status</th>{!readOnly && <th className="p-4 w-24">Ações</th>}</tr></thead><tbody>{rows.map(a => <tr key={a.id} className="border-t hover:bg-muted/40"><td className="p-4 font-bold min-w-48">{a.title}</td><td className="p-4 text-muted-foreground min-w-36">{a.kind}</td><td className="p-4">{organizations.find(o => o.id === a.organization_id)?.name || "—"}</td><td className="p-4 whitespace-nowrap">{formatDate(a.start_date)}</td><td className="p-4 whitespace-nowrap"><span className={`text-xs px-2 py-1 rounded ${a.status === "Concluída" ? "bg-accent text-accent-foreground" : "bg-secondary text-secondary-foreground"}`}>{a.status}</span></td>{!readOnly && <td className="p-4"><RowActions edit={() => onEdit(a)} remove={() => onDelete(a)} /></td>}</tr>)}</tbody></table>{rows.length === 0 && <Empty text="Nenhuma atividade encontrada. Cadastre uma para começar." />}</>; }
function Bar({ label, count, total }: { label: string; count: number; total: number }) { return <div><div className="flex justify-between gap-3 text-xs mb-2"><span className="text-muted-foreground">{label}</span><b>{count}</b></div><div className="h-2 rounded-full bg-secondary overflow-hidden"><div className="h-full bg-primary rounded-full" style={{ width: `${total ? count / total * 100 : 0}%` }} /></div></div>; }
function CalendarGrid({ date, rows, onSelect }: { date: Date; rows: ActivityRow[]; onSelect: (a: ActivityRow) => void }) { const first = new Date(date.getFullYear(), date.getMonth(), 1).getDay(); const days = new Date(date.getFullYear(), date.getMonth()+1, 0).getDate(); const cells = Array.from({ length: first + days }, (_, i) => i - first + 1); return <div className="p-3 md:p-5"><div className="grid grid-cols-7 text-center text-xs font-bold text-muted-foreground mb-2">{["Dom", "Seg", "Ter", "Qua", "Qui", "Sex", "Sáb"].map(x => <div key={x} className="py-2">{x}</div>)}</div><div className="grid grid-cols-7 border-t border-l">{cells.map((day, i) => { const key = day > 0 ? `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(day).padStart(2,"0")}` : ""; const daily = rows.filter(a => a.start_date === key); return <div key={i} className="min-h-20 md:min-h-28 border-r border-b p-1 md:p-2 overflow-hidden">{day > 0 && <><span className={`inline-grid place-items-center w-6 h-6 text-xs rounded-full ${key === new Date().toISOString().slice(0,10) ? "bg-primary text-primary-foreground" : ""}`}>{day}</span>{daily.slice(0, 2).map(a => <Button key={a.id} variant="ghost" onClick={() => onSelect(a)} title={a.title} className="block w-full h-auto min-h-5 p-1 mt-1 text-left text-[10px] md:text-xs bg-secondary text-secondary-foreground truncate rounded-sm justify-start">{a.title}</Button>)}{daily.length > 2 && <span className="text-[10px] text-muted-foreground">+{daily.length - 2}</span>}</>}</div>; })}</div></div>; }

type LinkedActivity = { description: string; status: string; start_date: string; end_date: string };
type Outcome = { title: string; status: string; start_date: string; end_date: string; activities: LinkedActivity[] };
const emptyLinkedActivity = (): LinkedActivity => ({ description: "", status: "Não iniciada", start_date: "", end_date: "" });
const normalizeOutcomes = (value: Json): Outcome[] => Array.isArray(value) ? value.filter((item): item is Record<string, Json | undefined> => Boolean(item) && typeof item === "object" && !Array.isArray(item)).map(item => ({
  title: typeof item['title'] === "string" ? item['title'] : "",
  status: typeof item['status'] === "string" ? item['status'] : "Não iniciada",
  start_date: typeof item['start_date'] === "string" ? item['start_date'] : "",
  end_date: typeof item['end_date'] === "string" ? item['end_date'] : "",
  activities: Array.isArray(item['activities']) ? item['activities'].filter((activity): activity is Record<string, Json | undefined> => Boolean(activity) && typeof activity === "object" && !Array.isArray(activity)).map(activity => ({
    description: typeof activity['description'] === "string" ? activity['description'] : "",
    status: typeof activity['status'] === "string" ? activity['status'] : "Não iniciada",
    start_date: typeof activity['start_date'] === "string" ? activity['start_date'] : "",
    end_date: typeof activity['end_date'] === "string" ? activity['end_date'] : "",
  })) : typeof item['activities'] === "string" && item['activities'].trim() ? [{ ...emptyLinkedActivity(), description: item['activities'] }] : [],
})) : [];
const activityDefaults = { kind: "Atividade geral", title: "", description: "", status: "Não iniciada", start_date: "", end_date: "", organization_id: "", axis: "", problem: "", problem_description: "", solution: "", solution_description: "", objectives: "", expected_results: "", achieved_results: "", participants: "", agenda: "", referrals: "", work_done: "" };
const orgDefaults = { name: "", kind: "Empresa", document: "", sector: "", size: "", maturity: "", region: "", contact: "", email: "", phone: "", address: "", stage: "Prospecção", demand: "", referral: "", notes: "" };
const actorDefaults = { institution_type: "", document: "", institution_name: "", phone: "", address: "", actor_name: "", position: "", birth_date: "", email: "" };
function Editor({ kind, row, userId, userName, organizations, actors, coordinationParticipants, onClose, onSaved, onError }: { kind: "activity" | "organization" | "actor" | "profile"; row: ActivityRow | Organization | Actor | null; userId: string; userName: string; organizations: Organization[]; actors: Actor[]; coordinationParticipants: CoordinationParticipant[]; onClose: () => void; onSaved: () => void; onError: (message: string) => void }) {
  const initial = kind === "activity" ? activityDefaults : kind === "organization" ? orgDefaults : kind === "actor" ? actorDefaults : { full_name: userName, phone: "", governance: "", region: "" };
  const [values, setValues] = useState<Record<string, string>>(() => Object.fromEntries(Object.entries(initial).map(([k, v]) => [k, row && k in row ? String((row as unknown as Record<string, unknown>)[k] ?? "") : String(v)])));
  const [outcomes, setOutcomes] = useState<Outcome[]>(() => kind === "activity" && row && "outcomes" in row ? normalizeOutcomes(row.outcomes) : []);
  const [files, setFiles] = useState<File[]>([]); const [savedEvidence, setSavedEvidence] = useState<string[]>(() => kind === "activity" && row && "evidence" in row && Array.isArray(row.evidence) ? row.evidence.filter((x): x is string => typeof x === "string") : []);
  const [busy, setBusy] = useState(false); const [message, setMessage] = useState(""); const [previewUrls, setPreviewUrls] = useState<Record<string, string>>({});
  const set = (key: string, value: string) => setValues(v => ({ ...v, [key]: value }));
  useEffect(() => { if (!savedEvidence.length) return; let cancelled = false; Promise.all(savedEvidence.map(async path => { const { data } = await supabase.storage.from("ari-evidence").createSignedUrl(path, 3600); return [path, data?.signedUrl || ""] as const; })).then(pairs => { if (!cancelled) setPreviewUrls(Object.fromEntries(pairs)); }); return () => { cancelled = true; }; }, [savedEvidence]);
  const isPlan = values['kind'] === activityKinds[0]; const isMeeting = values['kind']?.includes("Reuni") || values['kind']?.includes("reuni"); const isOrganizer = values['kind'] === "Evento como organizador";
  async function submit(e: FormEvent) { e.preventDefault(); setBusy(true); setMessage("");
    try {
      if (kind === "profile") { const { error } = await supabase.from("profiles").upsert({ id: userId, full_name: (values['full_name'] || "").trim(), phone: values['phone'] || "", governance: values['governance'] || "", region: values['region'] || "" }); if (error) throw error; }
      if (kind === "organization") { const payload = { ...orgDefaults, ...values, owner_id: row && "owner_id" in row ? row.owner_id : userId }; const result = row ? await supabase.from("organizations").update(payload).eq("id", row.id) : await supabase.from("organizations").insert(payload); if (result.error) throw result.error; }
      if (kind === "actor") { const payload = { ...actorDefaults, ...values, birth_date: values['birth_date'] || null, owner_id: row && "owner_id" in row ? row.owner_id : userId }; const result = row ? await supabase.from("actors").update(payload).eq("id", row.id) : await supabase.from("actors").insert(payload); if (result.error) throw result.error; }
      if (kind === "activity") {
        const evidence = [...savedEvidence];
        for (const file of files) { const path = `${userId}/${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g, "_")}`; const { error } = await supabase.storage.from("ari-evidence").upload(path, file); if (error) throw error; evidence.push(path); }
         const payload = { ...activityDefaults, ...values, title: values['kind'] === "Reunião de governança" || values['kind'] === "Reunião com a coordenação" ? `${values['kind']}${values['start_date'] ? ` - ${formatDate(values['start_date'])}` : ""}` : isPlan ? `Plano de estratégias${values['axis'] ? ` - ${values['axis']}` : values['start_date'] ? ` - ${formatDate(values['start_date'])}` : ""}` : values['title'] || "", start_date: values['start_date'] || null, end_date: values['end_date'] || null, organization_id: values['kind'] === "Reunião de governança" || values['kind'] === "Reunião com a coordenação" || values['kind'] === "Evento como ouvinte" ? null : values['organization_id'] || null, agenda: values['kind'] === "Reunião de governança" ? "" : values['agenda'] || "", owner_id: row && "owner_id" in row ? row.owner_id : userId, outcomes: outcomes as unknown as Json, evidence: evidence as Json, updated_at: new Date().toISOString() };
        const result = row ? await supabase.from("activities").update(payload).eq("id", row.id) : await supabase.from("activities").insert(payload); if (result.error) throw result.error;
      }
      onSaved();
    } catch (error) { const text = error instanceof Error ? error.message : "Erro ao salvar registro."; setMessage(text); onError(text); } finally { setBusy(false); }
  }
  const f = (label: string, name: string, opts?: { type?: string; options?: (string | { value: string; label: string })[]; textarea?: boolean; required?: boolean }) => field(label, name, values[name] || "", set, opts);
  const title = kind === "activity" ? "atividade" : kind === "organization" ? "organização" : kind === "actor" ? "ator da governança" : "perfil";
  return <div className="fixed inset-0 z-50 bg-foreground/50 flex justify-end" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><div role="dialog" aria-modal="true" aria-label={`${row ? "Editar" : "Novo"} ${title}`} className="bg-background w-full max-w-2xl h-full flex flex-col shadow-xl"><div className="bg-card border-b px-5 md:px-7 py-5 flex items-center justify-between"><div><h2 className="text-xl font-bold">{kind === "profile" ? "Meu perfil" : `${row ? "Editar" : "Novo"} ${title}`}</h2><p className="text-xs text-muted-foreground mt-1">{kind === "activity" ? "Preencha os detalhes e registre os resultados." : "Preencha as informações abaixo."}</p></div><Button variant="ghost" size="icon" aria-label="Fechar" onClick={onClose}><X /></Button></div><form id="editor-form" onSubmit={submit} className="flex-1 overflow-y-auto px-5 md:px-7 py-6 space-y-6">
  {kind === "profile" && <div className="grid sm:grid-cols-2 gap-4">{f("Nome completo", "full_name", { required: true })}{f("Telefone", "phone", { type: "tel" })}{f("Região atendida", "region")}{f("Governança atendida", "governance")}</div>}
  {kind === "organization" && <><div className="grid sm:grid-cols-2 gap-4">{f("Nome da organização", "name", { required: true })}{f("Tipo", "kind", { options: ["Empresa", "Startup", "Universidade", "ICT", "Entidade de apoio", "Poder público", "Outro"] })}{f("CNPJ / CPF", "document")}{f("Setor", "sector")}{f("Porte", "size", { options: ["Micro", "Pequeno", "Médio", "Grande", "Não se aplica"] })}{f("Maturidade em inovação", "maturity", { options: ["Inicial", "Em desenvolvimento", "Consolidada"] })}{f("Região", "region")}{f("Etapa do atendimento", "stage", { options: stages })}{f("Pessoa de contato", "contact")}{f("E-mail", "email", { type: "email" })}{f("Telefone", "phone", { type: "tel" })}{f("Endereço", "address")}</div>{f("Demandas", "demand", { textarea: true })}{f("Encaminhamentos", "referral", { textarea: true })}{f("Observações / histórico", "notes", { textarea: true })}</>}
  {kind === "actor" && <><div className="grid sm:grid-cols-2 gap-4">{f("Tipo de instituição", "institution_type", { options: ["Empresa", "Universidade", "Governo", "Entidade de apoio", "ICT", "Outro"] })}{f("CNPJ / CPF", "document")}{f("Nome da instituição", "institution_name", { required: true })}{f("Telefone", "phone", { type: "tel" })}{f("Endereço", "address")}{f("Nome do ator", "actor_name", { required: true })}{f("Cargo", "position")}{f("Data de nascimento", "birth_date", { type: "date" })}{f("E-mail", "email", { type: "email" })}</div></>}
   {kind === "activity" && <><div className="grid sm:grid-cols-2 gap-4">{f("Tipo de atividade", "kind", { options: activityKinds })}{values['kind'] !== "Reunião de governança" && values['kind'] !== "Reunião com a coordenação" && values['kind'] !== "Evento como ouvinte" && f("Status", "status", { options: statuses })}{!isPlan && values['kind'] !== "Reunião de governança" && values['kind'] !== "Reunião com a coordenação" && f(isMeeting ? "Título da reunião" : "Título da atividade", "title", { required: true })}{values['kind'] !== "Reunião de governança" && values['kind'] !== "Reunião com a coordenação" && values['kind'] !== "Evento como ouvinte" && f("Organização vinculada", "organization_id", { options: organizations.map(o => ({ value: o.id, label: o.name })) })}</div><div className="grid sm:grid-cols-2 gap-4">{f(isMeeting ? "Data da reunião" : "Data de início", "start_date", { type: "date" })}{!isMeeting && f("Data de conclusão", "end_date", { type: "date" })}</div>{!isMeeting && f("Descrição", "description", { textarea: true })}
     {isPlan && <><h3 className="font-bold border-b pb-2">Plano de estratégias</h3>{f("Eixo da atividade", "axis", { options: axes })}{f("Problema", "problem")}{f("Descrição do problema", "problem_description", { textarea: true })}{f("Solução", "solution")}{f("Descrição da solução", "solution_description", { textarea: true })}<div className="border-t pt-4 flex flex-wrap justify-between items-center gap-2"><h3 className="font-bold">Resultados esperados</h3><Button type="button" variant="outline" size="sm" onClick={() => setOutcomes([...outcomes, { title: "", status: "Não iniciada", start_date: "", end_date: "", activities: [] }])}><Plus /> Inserir resultado</Button></div>{outcomes.map((outcome, i) => <div key={i} className="app-panel p-4 space-y-3"><div className="flex justify-between items-center"><b className="text-sm">Resultado {i + 1}</b><Button type="button" variant="ghost" size="icon" aria-label="Remover resultado" onClick={() => setOutcomes(outcomes.filter((_, index) => index !== i))}><Trash2 /></Button></div>{field("Resultado esperado", "title", outcome.title, (_, v) => setOutcomes(outcomes.map((x,j) => j === i ? { ...x, title: v } : x)))}<div className="grid sm:grid-cols-3 gap-3">{([ ["Status", "status", "select"], ["Início", "start_date", "date"], ["Conclusão", "end_date", "date"] ] as const).map(([label, key, type]) => field(label, key, outcome[key], (_, v) => setOutcomes(outcomes.map((x,j) => j === i ? { ...x, [key]: v } : x)), type === "select" ? { options: statuses } : { type }))}</div><div className="border-t pt-3 flex flex-wrap items-center justify-between gap-2"><h4 className="text-sm font-bold">Atividades vinculadas</h4><Button type="button" variant="outline" size="sm" onClick={() => setOutcomes(current => current.map((x, j) => j === i ? { ...x, activities: [...x.activities, emptyLinkedActivity()] } : x))}><Plus /> Adicionar atividade</Button></div>{outcome.activities.map((activity, activityIndex) => <div key={activityIndex} className="border-l-2 border-primary bg-muted/40 p-3 space-y-3"><div className="flex items-center justify-between"><span className="text-xs font-bold text-muted-foreground">Atividade {activityIndex + 1}</span><Button type="button" variant="ghost" size="icon" aria-label={`Remover atividade ${activityIndex + 1}`} onClick={() => setOutcomes(current => current.map((x, j) => j === i ? { ...x, activities: x.activities.filter((_, k) => k !== activityIndex) } : x))}><Trash2 /></Button></div>{field("Descrição da atividade", "description", activity.description, (_, v) => setOutcomes(current => current.map((x, j) => j === i ? { ...x, activities: x.activities.map((a, k) => k === activityIndex ? { ...a, description: v } : a) } : x)), { textarea: true })}<div className="grid sm:grid-cols-3 gap-3">{([ ["Status", "status", "select"], ["Data de início", "start_date", "date"], ["Data de conclusão", "end_date", "date"] ] as const).map(([label, key, type]) => field(label, key, activity[key], (_, v) => setOutcomes(current => current.map((x, j) => j === i ? { ...x, activities: x.activities.map((a, k) => k === activityIndex ? { ...a, [key]: v } : a) } : x)), type === "select" ? { options: statuses } : { type }))}</div></div>)}</div>)}</>}
     {!isPlan && <>{isMeeting && <>{f("Objetivos da reunião", "objectives", { textarea: true })}{values['kind'] !== "Reunião de governança" && f("Pauta debatida", "agenda", { textarea: true })}{values['kind'] === "Reunião de governança" ? <ParticipantSelector actors={actors} value={values['participants'] || ""} onChange={value => set("participants", value)} /> : values['kind'] === "Reunião com a coordenação" ? <CoordinationParticipantSelector users={coordinationParticipants} value={values['participants'] || ""} onChange={value => set("participants", value)} /> : f("Participantes", "participants", { textarea: true })}{values['kind'] === "Reunião de governança" && f("Atividades do plano de ações discutidas", "work_done", { textarea: true })}{f("Encaminhamentos", "referrals", { textarea: true })}</>}{!isMeeting && <>{isOrganizer && f("Atividades realizadas", "work_done", { textarea: true })}{f("Objetivos", "objectives", { textarea: true })}</>}{f("Resultados esperados", "expected_results", { textarea: true })}{f("Resultados alcançados", "achieved_results", { textarea: true })}</>}
    <div className="border-t pt-5"><h3 className="font-bold">Evidências</h3><p className="text-xs text-muted-foreground mt-1 mb-3">Até três imagens, com no máximo 10 MB por arquivo.</p><label className="flex gap-2 items-center border border-dashed rounded-md p-4 text-sm cursor-pointer hover:bg-muted"><Paperclip size={17} /> Selecionar imagens<input type="file" accept="image/*" multiple className="sr-only" onChange={e => { const selected = Array.from(e.target.files || []).filter(f => f.type.startsWith("image/") && f.size <= 10 * 1024 * 1024); if (selected.length + savedEvidence.length > 3) setMessage("São permitidas até três imagens por atividade."); else { setFiles(selected); setMessage(""); } }} /></label>{files.map(file => <p key={file.name} className="text-xs mt-2">{file.name}</p>)}{savedEvidence.length > 0 && <div className="grid grid-cols-3 gap-3 mt-3">{savedEvidence.map(path => <div key={path} className="relative">{previewUrls[path] && <a href={previewUrls[path]} target="_blank" rel="noreferrer"><img src={previewUrls[path]} alt="Evidência da atividade" className="w-full aspect-square rounded object-cover border" /></a>}<Button type="button" variant="destructive" size="icon" title="Remover evidência" className="absolute right-1 top-1 h-6 w-6" onClick={() => setSavedEvidence(savedEvidence.filter(x => x !== path))}><X /></Button></div>)}</div>}</div></>}
  {message && <p role="alert" className="bg-secondary text-primary text-sm p-3 rounded">{message}</p>}
</form><div className="bg-card border-t p-4 md:px-7 flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancelar</Button><Button type="submit" form="editor-form" disabled={busy}>{busy ? "Salvando..." : "Salvar registro"}</Button></div></div></div>;
}

function ParticipantSelector({ actors, value, onChange }: { actors: Actor[]; value: string; onChange: (value: string) => void }) {
  const selected = value.split("\n").map(name => name.trim()).filter(Boolean);
  const toggle = (name: string) => onChange(selected.includes(name) ? selected.filter(item => item !== name).join("\n") : [...selected, name].join("\n"));
  return <fieldset className="min-w-0"><legend className="app-label">Participantes</legend><div className="max-h-56 overflow-y-auto rounded-md border bg-card p-2">{actors.length ? actors.map(actor => <label key={actor.id} className="flex cursor-pointer items-start gap-3 rounded px-3 py-2.5 hover:bg-muted"><input type="checkbox" className="mt-1 h-4 w-4 accent-primary" checked={selected.includes(actor.actor_name)} onChange={() => toggle(actor.actor_name)} /><span className="min-w-0"><span className="block text-sm font-medium">{actor.actor_name}</span><span className="block truncate text-xs text-muted-foreground">{actor.institution_name}{actor.position ? ` · ${actor.position}` : ""}</span></span></label>) : <p className="px-3 py-4 text-sm text-muted-foreground">Nenhum ator da governança cadastrado.</p>}</div></fieldset>;
}

function CoordinationParticipantSelector({ users, value, onChange }: { users: CoordinationParticipant[]; value: string; onChange: (value: string) => void }) {
  const selected = value.split("\n").map(name => name.trim()).filter(Boolean);
  const toggle = (name: string) => onChange(selected.includes(name) ? selected.filter(item => item !== name).join("\n") : [...selected, name].join("\n"));
  return <fieldset className="min-w-0"><legend className="app-label">Participantes</legend><div className="max-h-56 overflow-y-auto rounded-md border bg-card p-2">{users.length ? users.map(user => <label key={user.user_id} className="flex cursor-pointer items-center gap-3 rounded px-3 py-2.5 hover:bg-muted"><input type="checkbox" className="h-4 w-4 accent-primary" checked={selected.includes(user.full_name)} onChange={() => toggle(user.full_name)} /><span className="min-w-0 text-sm font-medium">{user.full_name}</span></label>) : <p className="px-3 py-4 text-sm text-muted-foreground">Nenhum usuário disponível para seleção.</p>}</div></fieldset>;
}
